command -v python3>/dev/null||exit 127;python3 -S -c 'import sys,re,functools;sys.set_int_max_str_digits(0);s=open(sys.argv[1]).read()if len(sys.argv)>1 else sys.stdin.read();R=[];K=set();exec("for l in s.splitlines():\n l=l.split(\"#\",1)[0].strip()\n if not l:continue\n m=re.fullmatch(r\"([^\\s,]+)\\s+([^\\s,]+)\\s*->\\s*([^\\s,]+)\\s+([^\\s,]+)\\s+([LRS])\",l)\n if not m:raise SystemExit(\"syntax: \"+l)\n a=m.groups();k=a[:2]\n if k in K:raise SystemExit(\"nondeterministic: \"+\" \".join(k))\n K.add(k);R.append(\",\".join(a))");p=";".join(R);E=lambda x:functools.reduce(lambda a,b:a*257+b+1,x.encode(),1);g=E(p);n=g;a=[];exec("while n>1:\n n,r=divmod(n,257);a.append(r-1)");assert bytes(a[::-1]).decode()==p;print("PROGRAM="+repr(p));print("GPROGRAM="+str(g));print("RULES="+str(len(R)))' "$@"
